parameters.jsCode:
// Get AI output
const aiOutput = $json.output || $json.text || $json.response;

// Remove markdown if AI accidentally returns it
const clean = aiOutput
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(clean);
} catch (err) {
  parsed = {
    intent: "human",
    reply: "I'm sorry, I couldn't understand your request. A team member will assist you shortly.",
    customer_name: "",
    email: "",
    phone: "",
    appointment_date: "",
    appointment_time: "",
    service: "",
    requires_human: true
  };
}

// Merge original data with parsed AI output
return [
  {
    json: {
      ...$json,
      ...parsed
    }
  }
];

const events = $input.all();

const current = $('Code').first().json;

let isAvailable = true;

if (
  events.length > 0 &&
  Object.keys(events[0].json).length > 0
) {
  isAvailable = false;
}

return [
  {
    json: {
      ...current,
      isAvailable,
      eventCount: events.length
    }
  }
];

const item = $input.first().json;

const missingFields = [];

if (!item.service) {
  missingFields.push("service");
}

if (!item.appointment_date) {
  missingFields.push("appointment_date");
}

if (!item.appointment_time) {
  missingFields.push("appointment_time");
}

item.missingFields = missingFields;
item.isComplete = missingFields.length === 0;

return [{ json: item }];

