parameters.jsCode:
const item = $input.first().json;

// Use the Time field (ISO string)
const dateObj = new Date(item.Time);

// Format Date
const formattedDate = new Intl.DateTimeFormat('en-IN', {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric',
  timeZone: 'Asia/Kolkata'
}).format(dateObj);

// Format Time
const formattedTime = new Intl.DateTimeFormat('en-IN', {
  hour: 'numeric',
  minute: '2-digit',
  hour12: true,
  timeZone: 'Asia/Kolkata'
}).format(dateObj);

return [{
  json: {
    ...item,
    FormattedDate: formattedDate,
    FormattedTime: formattedTime
  }
}];

const aiOutput = $json.output || "";

const clean = aiOutput
.replace(/```json/g,"")
.replace(/```/g,"")
.trim();

let parsed;

try{
    parsed = JSON.parse(clean);
}catch(e){
    parsed = {
        intent:"faq",
        reply:"Sorry, I couldn't understand your question.",
        requires_human:true
    };
}

return [{json:parsed}];

const lead = $input.first().json;

// Normalize values
const customerName = (lead.customer_name || "").trim();
const phone = (lead.phone || "").trim();
const service = (lead.service || "").trim();

const isComplete =
  customerName.length > 0 &&
  phone.length > 0 &&
  service.length > 0;

return [
  {
    json: {
      ...lead,
      customer_name: customerName,
      phone,
      service,
      isComplete
    }
  }
];

