parameters.jsCode:
// AI Output
const human = $input.first().json;

// Original customer message from Edit Fields node
const originalMessage = $('Edit Fields').first().json.message;

return [
  {
    json: {
      timestamp: new Date().toISOString(),

      customer_name: (human.customer_name || "").trim(),
      email: (human.email || "").trim(),
      phone: (human.phone || "").trim(),

      escalation_reason: "Customer Requested Human Assistance",

      customer_message: originalMessage,

      status: "Pending",

      requires_human: human.requires_human,

      reply:
        human.reply ||
        "Thank you for contacting us. Your request has been forwarded to one of our team members, who will contact you shortly."
    }
  }
];

